<script setup lang="ts">
import { computed, ref } from 'vue'
import AppIcon from '../AppIcon.vue'
import { devices, type Scene, useAutomationPreview } from '../../automation/preview'
const props = defineProps<{ scene: Scene }>()
const emit = defineEmits<{ close: []; save: [scene: Scene] }>()
const form = ref<Scene>(JSON.parse(JSON.stringify(props.scene))), error = ref('')
const store = useAutomationPreview()
const deviceName = computed(() => devices.find(d => d.id === form.value.device)?.name || '未选择设备')
const actionNames = { device: '控制设备', notification: '发送通知', connection: '输出到外部系统', delay: '延时执行' }
function changeKind(index: number) { const a = form.value.actions[index]!; a.target = a.kind === 'device' ? 'warmer-001' : a.kind === 'notification' ? store.templates[0]?.id || '' : a.kind === 'connection' ? store.connections.find(c => c.enabled)?.id || '' : ''; a.value = a.kind === 'device' ? '关闭加热' : a.kind === 'delay' ? '5' : '' }
function save(publish: boolean) {
  error.value = ''
  if (!form.value.name.trim()) error.value = '请填写场景名称'
  else if (!form.value.manual && (!form.value.device || !Number.isFinite(form.value.threshold) || !form.value.start || !form.value.end)) error.value = '请完整设置触发设备、温度阈值和生效时间'
  else if (!form.value.actions.length) error.value = '请至少添加一个执行动作'
  else if (!Number.isFinite(form.value.cooldown) || form.value.cooldown < 0) error.value = '请填写有效的冷却时间'
  else for (const a of form.value.actions) {
    if (a.kind === 'delay' && (!Number.isFinite(Number(a.value)) || Number(a.value) < 1 || Number(a.value) > 3600)) error.value = '延时需为 1～3600 秒'
    else if (a.kind === 'device' && (!devices.some(d => d.id === a.target) || !a.value)) error.value = '请选择设备及执行指令'
    else if (a.kind === 'connection' && !store.connections.some(c => c.id === a.target && c.enabled)) error.value = '请选择已启用的外部连接'
    else if (a.kind === 'notification' && !store.templates.some(t => t.id === a.target && store.channels.some(c => c.id === t.channelId && c.enabled))) error.value = '请选择具有已启用渠道的通知模板'
  }
  if (error.value) return
  emit('save', { ...JSON.parse(JSON.stringify(form.value)), status: publish ? 'running' : 'draft', version: form.value.version + (publish ? 1 : 0) })
}
</script>
<template>
  <div class="scene-editor"><div class="editor-heading"><div><button class="back-link" @click="emit('close')">← 返回场景自动化</button><h1>{{ form.id ? '编辑场景' : '新建场景' }}</h1><p>把日常需要的设备操作，变成自动发生的事。</p></div><div class="action-row"><el-button @click="save(false)">保存演示草稿</el-button><el-button type="primary" @click="save(true)">模拟发布</el-button></div></div><el-alert v-if="error" :title="error" type="error" :closable="false" class="editor-alert"/>
    <div class="editor-layout"><div class="editor-main"><section class="panel config-section"><div class="section-title"><span class="step-number neutral">·</span><div><h2>场景信息</h2><p>自动化由条件触发，一键执行由用户手动触发。</p></div></div><el-form label-position="top"><el-form-item label="场景名称（必填）"><el-input v-model="form.name" aria-label="场景名称" maxlength="60" placeholder="例如：婴儿房高温提醒"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description" aria-label="场景说明" maxlength="200"/></el-form-item><el-form-item label="场景类型"><el-radio-group v-model="form.manual"><el-radio-button :value="false">自动化</el-radio-button><el-radio-button :value="true">一键执行</el-radio-button></el-radio-group></el-form-item></el-form></section>
      <section v-if="!form.manual" class="panel config-section"><div class="section-title"><span class="step-number">当</span><div><h2>触发条件</h2><p>设备上报温度，并且满足以下条件时触发。</p></div></div><el-form label-position="top"><el-form-item label="触发设备"><el-select v-model="form.device" aria-label="触发设备"><el-option v-for="d in devices" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item><div class="scene-condition"><span>上报温度</span><strong>大于</strong><el-input-number v-model="form.threshold" aria-label="触发温度" :min="-50" :max="150"/><span>℃</span></div><div class="form-columns time-fields"><el-form-item label="每天生效时间"><div class="time-range"><el-input v-model="form.start" type="time" aria-label="开始时间"/><span>至</span><el-input v-model="form.end" type="time" aria-label="结束时间"/></div></el-form-item><el-form-item label="触发冷却（分钟）"><el-input-number v-model="form.cooldown" aria-label="冷却时间" :min="0" :max="1440"/></el-form-item></div></el-form><p class="field-help">跨午夜时间段可用，例如 22:00 至 06:00。冷却时间内不重复触发。</p></section>
      <section class="panel config-section"><div class="section-title"><span class="step-number green">就</span><div><h2>执行动作</h2><p>按列表顺序依次执行，可组合设备、通知和外部系统。</p></div></div><div v-for="(action, index) in form.actions" :key="index" class="scene-action"><div class="scene-action-heading"><span>动作 {{ String(index + 1).padStart(2, '0') }}</span><el-button text :aria-label="`移除动作 ${index + 1}`" @click="form.actions.splice(index, 1)"><AppIcon name="close" :size="15"/></el-button></div><el-form label-position="top"><el-form-item label="动作类型"><el-select v-model="action.kind" :aria-label="`动作类型 ${index + 1}`" @change="changeKind(index)"><el-option v-for="(label, kind) in actionNames" :key="kind" :label="label" :value="kind"/></el-select></el-form-item><div v-if="action.kind === 'device'" class="form-columns"><el-form-item label="目标设备"><el-select v-model="action.target"><el-option v-for="d in devices" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item><el-form-item label="执行指令"><el-select v-model="action.value"><el-option label="关闭加热" value="关闭加热"/><el-option label="开启加热" value="开启加热"/></el-select></el-form-item></div><el-form-item v-else-if="action.kind === 'notification'" label="通知模板"><el-select v-model="action.target"><el-option v-for="t in store.templates" :key="t.id" :label="t.name" :value="t.id"/></el-select></el-form-item><el-form-item v-else-if="action.kind === 'connection'" label="外部连接"><el-select v-model="action.target"><el-option v-for="c in store.connections" :key="c.id" :label="c.name" :value="c.id" :disabled="!c.enabled"/></el-select></el-form-item><el-form-item v-else label="等待秒数"><el-input v-model="action.value" type="number" min="1" max="3600"/></el-form-item></el-form></div><el-button class="add-action" :disabled="form.actions.length >= 8" @click="form.actions.push({ kind: 'device', target: 'warmer-001', value: '关闭加热' })">＋ 添加执行动作</el-button></section>
    </div><aside class="editor-aside"><section class="panel test-panel"><p class="eyebrow">SCENE SUMMARY</p><h2 class="scene-summary-title">{{ form.name || '你的新场景' }}</h2><div class="scene-summary-step"><span class="step-number">当</span><div><strong>{{ form.manual ? '手动点击执行' : deviceName }}</strong><p v-if="!form.manual">温度上报大于 {{ form.threshold }}℃</p><p v-else>通过控制台或应用发起</p></div></div><div class="scene-summary-step"><span class="step-number green">就</span><div><strong>顺序执行 {{ form.actions.length }} 个动作</strong><p v-for="(a, i) in form.actions" :key="i">{{ i + 1 }}. {{ actionNames[a.kind] }}{{ a.kind === 'device' ? ` · ${a.value}` : a.kind === 'delay' ? ` · ${a.value} 秒` : '' }}</p></div></div><div v-if="!form.manual" class="scope-note"><AppIcon name="clock" :size="15"/>{{ form.start }}—{{ form.end }} · 冷却 {{ form.cooldown }} 分钟</div></section><div class="editor-tip"><AppIcon name="shield" :size="17"/><p>当前为演示场景。发布和试运行不会控制真实设备，也不会发送通知。</p></div></aside></div>
  </div>
</template>
